-- Credits move from code into the database, in Harvard form, so the admin can
-- edit them, upload book covers and keep a gallery of the images each source covers.

create table public.credits (
  id bigint generated always as identity primary key,
  section text not null check (section in ('rules', 'pictures', 'icons', 'code')),
  authors text,
  year text,
  title text not null,
  medium text,
  place text,
  publisher text,
  url text,
  accessed date,
  license text,
  license_url text,
  used_for text,
  cover_url text,
  images text[] not null default '{}',
  sort integer not null default 0
);

alter table public.credits enable row level security;
create policy "Anyone can read the credits" on public.credits for select using (true);
create policy "Admins edit the credits" on public.credits for all to authenticated
  using ((select public.my_role()) = 'admin') with check ((select public.my_role()) = 'admin');
grant select on public.credits to anon, authenticated;
grant insert, update, delete on public.credits to authenticated;

